<script>function editRecord(r){location.href='<?php echo XC_URL; ?>/backend/outpatient/edit/'+r.id}</script>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
$('.delete-outpatient').on('submit',function(e){
    e.preventDefault();var form=$(this);Swal.fire({title:'Xóa bản ghi?',text:'Dữ liệu sẽ được xóa khỏi danh sách.',icon:'warning',showCancelButton:true,confirmButtonText:'Xóa',cancelButtonText:'Hủy'}).then(function(result){if(!result.isConfirmed)return;
    var button=form.find('button').prop('disabled',true);
    $.ajax({url:'<?php echo XC_URL; ?>/api/deleteOutpatient',type:'POST',data:form.serialize(),dataType:'json'}).done(function(res){
        Swal.fire({icon:res.success?'success':'error',title:res.success?'Thành công':'Không thành công',text:res.message,timer:1600,showConfirmButton:false}).then(function(){if(res.success)location.reload();});
    }).fail(function(xhr){Swal.fire('Không thành công',xhr.responseJSON&&xhr.responseJSON.message?xhr.responseJSON.message:'Không thể xóa. Vui lòng thử lại.','error');}).always(function(){button.prop('disabled',false);});});
});
</script>
